```cpp
class AlmostGreat
{
public:
    double entry1(double a) {
        m_mutex.lock();
        m_a = a;
        doSomethingWithIt(m_a);
        double localA = m_a;
        m_mutex.unlock();
        // Hors mutex car très coûteuse et thread-safe
        return someHugeFunction(localA);
    }

    double entry2(double a, double b) {
        double c = a + b;
        m_mutex.lock();
        m_a += 2 * c;
        double res = m_a;
        m_mutex.unlock();
        return res;
    }

    double entry3(double a, double b) {
        double c = a + b;
        m_mutex.lock();
        m_a = 2 * c;
        // someSimpleFunction n'est pas explicitement thread-safe et est très rapide :
        // on la garde sous mutex par prudence.
        double d = someSimpleFunction(m_a);
        m_mutex.unlock();
        double e = 2 * d;
        return e;
    }

private:
    // This function uses a and modifies it
    void doSomethingWithIt(double &a);

    // This function do some very simple computation
    double someSimpleFunction(double a);

    // This function takes a lot of CPU time (yes, a lot)
    // It is thread-safe
    double someHugeFunction(double a);

    double m_a{0.0};
    PcoMutex m_mutex;
};
```

**Points clés :**
* Les calculs purement locaux (`double c = a + b;`, `double e = 2 * d;`) n'ont pas besoin d'être dans la section critique.
* Dans `entry1` et `entry2`, on copie `m_a` dans une variable locale **avant** `m_mutex.unlock()` pour éviter un data race lors de la lecture de `m_a`.
* `someHugeFunction(localA)` est exécutée **hors** du mutex : elle est thread-safe et consomme beaucoup de CPU, donc garder le mutex verrouillé bloquerait inutilement les autres threads.

