```cpp
class RacletteTic
{
private:
    PcoSemaphore mutex;
    PcoSemaphore waitEtudiant;
    PcoSemaphore waitPer;
    int nbEtudiants;
    int nbPer;

public:
    RacletteTic() : mutex(1), waitEtudiant(0), waitPer(0), nbEtudiants(0), nbPer(0)
    {
    }

    void etudiant()
    {
        mutex.acquire();
        nbEtudiants++;
        mutex.release();
        waitEtudiant.acquire();
    }

    void per()
    {
        mutex.acquire();
        nbPer++;
        mutex.release();
        waitPer.acquire();
    }

    int racleur()
    {
        mutex.acquire();
        int nbPersonnes = 0;

        if (nbPer > 0) {
            nbPer--;
            waitPer.release();
            nbPersonnes++;
        }

        while (nbEtudiants > 0 && nbPersonnes < 4) {
            nbEtudiants--;
            waitEtudiant.release();
            nbPersonnes++;
        }

        mutex.release();
        return nbPersonnes;
    }
};
```

**Points clés :**
* Pas de réveil perdu : même si un `racleur()` fait `release()` avant que le thread `etudiant()` ou `per()` n'ait exécuté `waitX.acquire()`, le sémaphore stocke le jeton et l'`acquire()` passera immédiatement.
* `racleur()` retourne directement `0` si personne n'est en attente.

